/bin/bash -lc "python - <<'PY'
import os, time
from bioblend.galaxy import GalaxyInstance
hid='bbd44e69cb8906b53419056e1844feba'; cid='9f9f157bc017a5ae'
with open(os.environ['GALAXY_API_KEY_FILE'],encoding='utf-8') as fh: key=fh.read().strip()
gi=GalaxyInstance(url='https://usegalaxy.org',key=key)
coll=gi.histories.show_dataset_collection(hid,cid)
dataset_ids=[]
for e in coll.get('elements',[]):
    obj=e.get('object') or {}
    did=obj.get('id')
    if did: dataset_ids.append(did)

ok=0; failed=[]
for idx,did in enumerate(dataset_ids,1):
    for attempt in range(8):
        try:
            gi.histories.update_dataset(hid,did,datatype='fasta')
            ok+=1
            break
        except Exception as exc:
            msg=str(exc)
            if '429' in msg and attempt < 7:
                time.sleep(5 + attempt*5)
                continue
            failed.append((did,msg))
            break
    if idx % 50 == 0:
        print('processed',idx,'ok',ok,'failed',len(failed),flush=True)
    time.sleep(0.35)
print('total',len(dataset_ids),'ok',ok,'failed',len(failed))
if failed: print('first_failure',failed[0][1])
PY"

